package br.com.oficina.infrastructure;
import br.com.oficina.domain.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.*; import org.springframework.test.web.servlet.MockMvc; import java.math.BigDecimal; import static org.junit.jupiter.api.Assertions.assertEquals; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class OrdemServicoIntegrationTest { @Autowired MockMvc mvc; @Autowired ClienteRepository clientes; @Autowired VeiculoRepository veiculos; @Autowired ServicoRepository servicos; @Autowired PecaRepository pecas; @Autowired JwtService jwt; @Test void criaOsCalculaOrcamentoEBaixaEstoque() throws Exception {Cliente c=clientes.save(new Cliente("52998224725","Ana",null,null));Veiculo v=veiculos.save(new Veiculo(c,"ABC1D23","Ford","Ka",2020));Servico s=servicos.save(new Servico("Troca de óleo",new BigDecimal("100.00"),30));Peca p=pecas.save(new Peca("Óleo",new BigDecimal("30.00"),2));String json="{\"documento\":\"52998224725\",\"placa\":\"ABC1D23\",\"servicos\":[\""+s.getId()+"\"],\"pecas\":{\""+p.getId()+"\":2}}";mvc.perform(post("/api/ordens-servico").header(HttpHeaders.AUTHORIZATION,"Bearer "+jwt.gerar("admin")).contentType(MediaType.APPLICATION_JSON).content(json)).andExpect(status().isCreated()).andExpect(jsonPath("$.total").value(160));assertEquals(0,pecas.findById(p.getId()).orElseThrow().getEstoque());} }
